fn test_cmphs_p_p_zi_combo_6_0_2420c000() {
    // Encoding: 0x2420C000
    // Test CMPHS_P.P.ZI__ field combination: size=0, imm7=3, Pg=0, Zn=0, Pd=0
    // Fields: Zn=0, Pg=0, size=0, Pd=0, imm7=3
    let encoding: u32 = 0x2420C000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "instruction 0x{:08X} should execute successfully",
        encoding
    );
}

