/// Requirement: FieldExtraction { field: "combination", bit_start: 0, bit_width: 32 }
/// Rm=30 (register index 30 (LR in some contexts))
#[test]
fn test_ld2b_z_p_br_contiguous_combo_2_c000_a43ec000() {
    // Encoding: 0xA43EC000
    // Test LD2B_Z.P.BR_Contiguous field combination: Rm=30, Pg=0, Rn=0, Zt=0
    // Fields: Rm=30, Pg=0, Zt=0, Rn=0
    let encoding: u32 = 0xA43EC000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "instruction 0x{:08X} should execute successfully",
        encoding
    );
}

